package run.ikaros.reading;
import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; import run.ikaros.resource.CreateResourceRequest; import run.ikaros.resource.ResourceService; import run.ikaros.resource.ResourceType;
@Service public class PersistentReadingCatalogService implements ReadingCatalogService {private final ResourceService resources;private final ReadingWorkRepository works;private final ReadingEditionRepository editions;private final ReadingVolumeRepository volumes;private final ReadingChapterRepository chapters;public PersistentReadingCatalogService(ResourceService r,ReadingWorkRepository w,ReadingEditionRepository e,ReadingVolumeRepository v,ReadingChapterRepository c){resources=r;works=w;editions=e;volumes=v;chapters=c;}
 @Override public Mono<ReadingWorkView> createWork(UUID o,CreateReadingWorkRequest r){ResourceType type=r.kind()==ReadingWorkKind.COMIC?ResourceType.COMIC:ResourceType.BOOK;String locale=r.locale()==null||r.locale().isBlank()?"en-US":r.locale();return resources.create(o,new CreateResourceRequest(type,r.title(),locale)).flatMap(x->works.save(new ReadingWorkEntity(null,o,x.id(),r.kind().name(),r.originalLanguage(),"ONGOING",null))).map(this::workView);}
 @Override public Flux<ReadingWorkView> listWorks(UUID o){return works.findAllByOwnerId(o).map(this::workView);}
 @Override public Mono<ReadingEditionView> createEdition(UUID o,UUID id,CreateReadingEditionRequest r){return work(o,id).flatMap(w->editions.save(new ReadingEditionEntity(null,o,id,r.name().trim(),r.language(),r.publisher(),r.source(),r.preferenceWeight(),"AVAILABLE",null))).map(this::editionView);}
 @Override public Flux<ReadingEditionView> listEditions(UUID o,UUID id){return work(o,id).flatMapMany(w->editions.findAllByOwnerIdAndWorkId(o,id).map(this::editionView));}
 @Override public Mono<ReadingVolumeView> createVolume(UUID o,UUID id,CreateReadingVolumeRequest r){return edition(o,id).flatMap(e->volumes.save(new ReadingVolumeEntity(null,id,r.kind(),r.displayLabel(),r.structuredNumber(),r.sortOrder(),r.title(),null))).map(this::volumeView);}
 @Override public Flux<ReadingVolumeView> listVolumes(UUID o,UUID id){return edition(o,id).flatMapMany(e->volumes.findAllByEditionIdOrderBySortOrderAsc(id).map(this::volumeView));}
 @Override public Mono<ReadingChapterView> createChapter(UUID o,UUID editionId,UUID volumeId,CreateReadingChapterRequest r){return edition(o,editionId).flatMap(e->works.findById(e.workId()).flatMap(w->(volumeId==null?Mono.just(new ReadingVolumeEntity(null,editionId,null,null,null,0,null,null)):volumes.findById(volumeId).filter(v->v.editionId().equals(editionId)).switchIfEmpty(Mono.error(new ConflictException("Volume 不属于该 Edition")))).flatMap(v->{String locale="en-US";return resources.create(o,new CreateResourceRequest(ResourceType.BOOK,r.title(),locale)).flatMap(x->chapters.save(new ReadingChapterEntity(null,o,w.id(),editionId,v.id(),x.id(),r.structuredNumber(),r.displayLabel(),r.title(),r.sortOrder(),r.contentKind(),r.pageCount(),r.textLength(),"AVAILABLE","ACTIVE",null)));}))).map(this::chapterView);}
 @Override public Flux<ReadingChapterView> listChapters(UUID o,UUID id){return edition(o,id).flatMapMany(e->chapters.findAllByOwnerIdAndEditionIdOrderBySortOrderAsc(o,id).map(this::chapterView));}
 private Mono<ReadingWorkEntity> work(UUID o,UUID id){return works.findById(id).filter(w->w.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Reading Work 不存在或无权访问")));}private Mono<ReadingEditionEntity> edition(UUID o,UUID id){return editions.findById(id).filter(e->e.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Reading Edition 不存在或无权访问")));}private ReadingWorkView workView(ReadingWorkEntity e){return new ReadingWorkView(e.id(),e.resourceId(),ReadingWorkKind.valueOf(e.kind()),e.originalLanguage());}private ReadingEditionView editionView(ReadingEditionEntity e){return new ReadingEditionView(e.id(),e.workId(),e.name(),e.language(),e.publisher(),e.source(),e.preferenceWeight(),e.availability());}private ReadingVolumeView volumeView(ReadingVolumeEntity e){return new ReadingVolumeView(e.id(),e.editionId(),e.kind(),e.displayLabel(),e.structuredNumber(),e.sortOrder(),e.title());}private ReadingChapterView chapterView(ReadingChapterEntity e){return new ReadingChapterView(e.id(),e.workId(),e.editionId(),e.volumeId(),e.resourceId(),e.structuredNumber(),e.displayLabel(),e.title(),e.sortOrder(),e.contentKind(),e.pageCount(),e.textLength(),e.availability());}}
